## Function to check if a number is prime
fn is_prime(n) =>
  when n < 2 { false } else {
    val is_divisible := false
    loop i from 2 to n - 1 {
      when n % i == 0 { is_divisible := true }
    }
    when is_divisible { false } else { true }
  }

## Testing the function
val result := is_prime(13)
shout(result)  ## prints true
```

